-- Migration 002: Compliance and creator profiles
CREATE TYPE creator_tier_type AS ENUM ('STANDARD','PREMIUM','VIP');
CREATE TYPE verification_status AS ENUM ('NOT_SUBMITTED','PENDING_REVIEW','APPROVED','REJECTED','EXPIRED');
CREATE TABLE creator_profiles (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID UNIQUE NOT NULL REFERENCES users(id) ON DELETE RESTRICT, handle VARCHAR(50) UNIQUE NOT NULL, banner_url TEXT, tagline VARCHAR(255), verification_status verification_status NOT NULL DEFAULT 'NOT_SUBMITTED', verified_at TIMESTAMPTZ, tax_onboarding_completed BOOLEAN NOT NULL DEFAULT FALSE, payout_onboarding_completed BOOLEAN NOT NULL DEFAULT FALSE, subscriber_count INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE performer_records_2257 (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), creator_id UUID NOT NULL REFERENCES creator_profiles(id) ON DELETE RESTRICT, performer_stage_name VARCHAR(100) NOT NULL, legal_name_encrypted BYTEA NOT NULL, dob DATE NOT NULL, id_type VARCHAR(50) NOT NULL, id_number_hash VARCHAR(128) NOT NULL, id_expiry_date DATE NOT NULL, custodian_name VARCHAR(100) NOT NULL, custodian_physical_address TEXT NOT NULL, id_scan_storage_path TEXT NOT NULL, verified_by_moderator_id UUID REFERENCES users(id), verification_timestamp TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE performer_consents (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), performer_record_id UUID NOT NULL REFERENCES performer_records_2257(id) ON DELETE RESTRICT, document_signature_hash VARCHAR(128) NOT NULL, consent_statement_version VARCHAR(20) NOT NULL, signed_at TIMESTAMPTZ NOT NULL, ip_address INET NOT NULL, user_agent TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
